<script setup lang="ts">
import { projectDifferences, projectFingerprint } from '#/api/creative-video/project-diff';
import { remoteProjects } from '#/api/creative-video/project-repository';
import { studioStorage } from '#/api/creative-video/storage';
import { useRoute, useRouter } from 'vue-router';
import { computed, ref, watch, onUnmounted } from 'vue';
import { ElDialog, ElButton, ElInput, ElInputNumber, ElMessage, ElMessageBox, ElTag } from 'element-plus';
import { brandApi } from '#/api/creative-video/settings';
import { allowed, currentRole, canEmulateRole } from '#/api/creative-video/permissions';
import type { StudioRole } from '#/api/creative-video/permissions';
import { projectApi, stages } from '#/api/creative-video';
import type { Project } from '#/api/creative-video';
import { confirmStage, invalidateFrom } from '#/api/creative-video/approvals';
import { creativeConcepts } from '#/api/creative-video/creative';
import { loadUnderstanding } from '#/api/creative-video/understanding';
import CreativePanel from './CreativePanel.vue';
import UnderstandingPanel from './UnderstandingPanel.vue';
import MockTools from './MockTools.vue';
import ProjectWizard from './ProjectWizard.vue';
import IntakePanel from './IntakePanel.vue';
import { intakeApi } from '#/api/creative-video/intake';
import { loadScript, validateBeats } from '#/api/creative-video/script';
import ScriptPlanner from './ScriptPlanner.vue';
import ProductionPanel from './ProductionPanel.vue';
const role=ref<StudioRole>(currentRole());
function switchRole(){studioStorage.setItem('vidcraft-role',role.value);window.location.reload();}
const route=useRoute();const router=useRouter();
const stepPaths=['ingest','understanding','angles','script','storyboard','animatic','generate','render'];
const projects = ref(projectApi.list());const projectSync=ref('本地缓存');
const syncBusy=new Set<number>();const conflict=ref<{local:Project;remote?:Project;revision:number;instance:string}>();let autosave:ReturnType<typeof setTimeout>|undefined;let disposed=false;onUnmounted(()=>{disposed=true;if(autosave)clearTimeout(autosave);});
async function syncProject(p:Project){if(syncBusy.has(p.id)||conflict.value?.local.id===p.id)return false;syncBusy.add(p.id);const fingerprint=projectFingerprint(p);try{projectSync.value='正在保存服务端';const response=await remoteProjects.save(JSON.parse(JSON.stringify(p)) as Project);p.serverRevision=response.revision;p.serverInstance=response.instance;save();projectSync.value=`服务端 R${response.revision} 已保存`;return true;}catch{projectSync.value='同步失败，本地草稿保留';try{const server=await remoteProjects.list();const record=server.items.find(r=>r.data.id===p.id);if((record?.revision??0)!==(p.serverRevision??0)||p.serverInstance&&server.instance!==p.serverInstance){conflict.value={local:p,remote:record?.data,revision:record?.revision??0,instance:server.instance};projectSync.value=record?'存在版本冲突，请比较后处理':'Mock服务已重置，请确认是否重新保存本地项目';}}catch{projectSync.value='服务连接中断，本地草稿保留，可手动重试';}return false;}finally{syncBusy.delete(p.id);if(!disposed&&!conflict.value&&projectFingerprint(p)!==fingerprint)autosave=setTimeout(()=>void syncProject(p),800);}}
async function resolveConflict(useLocal:boolean){const c=conflict.value;if(!c)return;if(!useLocal&&!c.remote)return;try{await ElMessageBox.confirm(useLocal?'确认以本地草稿为基础保存到当前远端版本？':'确认用远端项目替换本地项目字段？资料子资源和历史视频不会删除。','处理项目差异');}catch{return;}if(!useLocal&&c.remote)Object.assign(c.local,c.remote);c.local.serverRevision=c.revision;c.local.serverInstance=c.instance;conflict.value=undefined;save();if(useLocal)await syncProject(c.local);else projectSync.value='已采用远端项目字段';}
async function reloadRemote(){try{const response=await remoteProjects.list();for(const record of response.items){const p=projects.value.find(p=>p.id===record.data.id);if(!p)projects.value.push({...record.data,serverRevision:record.revision,serverInstance:response.instance});}save();ElMessage.success('已补充服务端项目；已有本地草稿不自动覆盖');}catch{ElMessage.warning('服务端项目读取失败');}}
const active = ref<Project>();
watch(()=>active.value?projectFingerprint(active.value):'',(_value,previous)=>{if(autosave)clearTimeout(autosave);const p=active.value;if(!p||!allowed('edit'))return;if(p.serverRevision===undefined&&(!previous||JSON.parse(previous).id!==p.id))return;projectSync.value='本地草稿已更新，等待自动同步';autosave=setTimeout(()=>void syncProject(p),1000);});
function open(p:Project){active.value=p;void router.push(`/studio/${p.id}/${stepPaths[p.stage]}`);}
watch(()=>route.fullPath,()=>{if(route.params.projectId){const p=projects.value.find(p=>String(p.id)===route.params.projectId);const step=stepPaths.indexOf(String(route.params.step));if(p&&step>=0&&step<=(reached.value[p.id]??p.stage)){active.value=p;p.stage=step;}else{ElMessage.warning('项目不存在或阶段尚未解锁');void router.replace('/projects');}}else active.value=undefined;});
const name = ref('');const wizard=ref(route.path==='/projects/new');const filter=ref('active');const order=ref('recent');
async function created(p:Project){if(!await syncProject(p))return;projects.value.unshift(p);wizard.value=false;save();open(p);}
async function rename(p:Project){try{const result=await ElMessageBox.prompt('请输入新名称','重命名',{inputValue:p.name});projectApi.rename(p,result.value);save();await syncProject(p);}catch{}}
async function remove(p:Project){try{await ElMessageBox.confirm('仅软删除项目，历史账务和任务将保留，可在回收站恢复。','删除项目');projectApi.softDelete(p);save();await syncProject(p);}catch{}}
async function duplicate(p:Project){const copy=projectApi.duplicate(p);if(!await syncProject(copy))return;projects.value.unshift(copy);save();ElMessage.success('已复制资料与创意草稿，不复制视频、任务和账务；素材引用请重新选择');}
const search = ref('');
const reached = ref<Record<number, number>>(JSON.parse(studioStorage.getItem('vidcraft-reached') || '{}'));
watch(projects, () => save(), { deep: true });
function navigate(i:number) { reached.value=JSON.parse(studioStorage.getItem('vidcraft-reached')||'{}'); if(active.value && i <= (reached.value[active.value.id] ?? active.value.stage)) {active.value.stage=i;open(active.value);} }
function proceed() { if(!allowed('review')){ElMessage.warning('当前角色不能确认审核');return;} if(!active.value) return; if(active.value.stage===1){if(studioStorage.getItem(`vidcraft-intake-dirty-${active.value.id}`)){ElMessage.warning('资料尚未同步确认，请重试');return;}if(!loadUnderstanding(active.value.id).confirmed||studioStorage.getItem(`vidcraft-understanding-dirty-${active.value.id}`)){ElMessage.warning('请确认结构化产品理解');return;}const intake=intakeApi.load(active.value.id);if(!intake.evidence.length||intake.confirmedRevision!==intake.revision){ElMessage.warning('请先核对并确认当前资料证据');return;}} if(active.value.stage===2&&studioStorage.getItem(`vidcraft-creative-dirty-${active.value.id}`)){ElMessage.warning('创意尚未成功同步，请重新锁定');return;} if(active.value.stage===2&&!JSON.parse(studioStorage.getItem(`vidcraft-creative-${active.value.id}`)||'{}').locked){ElMessage.warning('请保存并锁定创意方向');return;} if(active.value.stage===3){if(studioStorage.getItem(`vidcraft-script-dirty-${active.value.id}`)){ElMessage.warning('剧本有未保存或校验失败的修改，请保存后继续');return;}try{validateBeats(loadScript(active.value.id).beats,active.value.duration);}catch(e){ElMessage.warning((e as Error).message);return;}} if(active.value.stage===3&&!JSON.parse(studioStorage.getItem(`vidcraft-script-${active.value.id}`)||'{}').script?.trim()){ElMessage.warning('请先生成并核对完整剧本');return;} if(active.value.stage===4 && !studioStorage.getItem(`storyboard-approved-${active.value.id}`)) { ElMessage.warning('请先确认分镜'); return; } if(active.value.stage===6) { const raw=studioStorage.getItem(`production-${active.value.id}`); if(!raw || !(JSON.parse(raw).shots as {adopted?:number}[]).every(s=>s.adopted)) { ElMessage.warning('请先审核采用全部镜头'); return; } } next(); }
watch(()=>active.value ? [active.value.id,active.value.url,active.value.report,active.value.angle,active.value.duration] : undefined,(value,previous)=>{if(!active.value||!value||!previous||value[0]!==previous[0])return;const stage=value.slice(1).findIndex((v,i)=>v!==previous[i+1]);if(stage>=0){invalidateFrom(active.value.id,stage);reached.value=JSON.parse(studioStorage.getItem('vidcraft-reached')||'{}');ElMessage.info('上游已修改，后续阶段需要重新核对；历史视频与成片保留');}});
const visible = computed(() => projects.value.filter(p => p.name.includes(search.value)&& (filter.value==='deleted'?p.deleted:!p.deleted&&(filter.value==='archived'?p.archived:!p.archived))).sort((a,b)=>order.value==='name'?a.name.localeCompare(b.name):b.id-a.id));
if(route.params.projectId){const p=projects.value.find(p=>String(p.id)===route.params.projectId);const step=stepPaths.indexOf(String(route.params.step));if(p&&step>=0&&step<=(reached.value[p.id]??p.stage)){active.value=p;p.stage=step;}}
const angles = computed(()=>{void active.value?.stage;return active.value?creativeConcepts(active.value.id).map(c=>c.title):[];});
function save() { projectApi.save(projects.value); }
function create() {if(!allowed('edit')){ElMessage.warning('当前角色不能创建项目');return;}wizard.value=true;}
function next() { reached.value=JSON.parse(studioStorage.getItem('vidcraft-reached')||'{}'); if (!active.value) return; if (active.value.stage === 0 && !/^https?:\/\//.test(active.value.url)) { ElMessage.warning('请输入有效的 http / https 产品网址'); return; } confirmStage(active.value.id,active.value.stage,JSON.stringify([active.value.url,active.value.report,active.value.angle,active.value.duration])); active.value.stage = Math.min(7, active.value.stage + 1); reached.value[active.value.id]=Math.max(reached.value[active.value.id]??0,active.value.stage); studioStorage.setItem('vidcraft-reached',JSON.stringify(reached.value)); save(); open(active.value); }
</script>
<template>
  <div class="creative">
    <header><div class="brand">◈ <b>{{ brandApi.load().name }}</b><span>创意制片工作台</span></div><select v-model="role" @change="switchRole"><option :disabled="!canEmulateRole('owner')" value="owner">拥有者（演示）</option><option :disabled="!canEmulateRole('editor')" value="editor">编辑者（演示）</option><option :disabled="!canEmulateRole('reviewer')" value="reviewer">审核者（演示）</option><option :disabled="!canEmulateRole('viewer')" value="viewer">只读访客（演示）</option></select><ElTag type="warning" effect="plain">MOCK · 演示模式</ElTag></header>
    <template v-if="!active"><p>{{ projectSync }} <ElButton @click="reloadRemote">读取服务端项目</ElButton></p><MockTools/>
      <ProjectWizard v-if="wizard" :initial-name="name" @created="created" @cancel="wizard=false"/><section v-else class="hero"><div class="eyebrow">YOUR PRODUCT. A STORY WORTH TELLING.</div><h1>好产品，值得一个好故事。</h1><p>从一个产品网址出发，让 AI 与你一起发现创意、打磨分镜，把价值变成被看见的故事。</p><div class="create"><ElInput v-model="name" placeholder="给你的下一个创意项目起个名字" @keyup.enter="create"/><ElButton type="primary" size="large" @click="create">＋ 新建项目</ElButton></div><small>先理解，再创作。每一个关键步骤，都由你掌控。</small><div class="orb">✳</div></section>
      <div class="section-title"><h2>我的创意项目 <span>{{ projects.length }}</span></h2><ElInput v-model="search" placeholder="搜索项目" style="width:240px"/></div>
      <div><select v-model="filter"><option value="active">进行中</option><option value="archived">已归档</option><option value="deleted">回收站</option></select><select v-model="order"><option value="recent">最近创建</option><option value="name">名称排序</option></select></div><div class="grid"><article v-for="(p,i) in visible" :key="p.id" class="project"><div class="cover" :class="`cover-${i%3}`"><span>0{{ i+1 }}</span><strong>{{ p.name.slice(0,8) }}</strong><i>CREATIVE FILM ↗</i></div><h3>{{ p.name }}</h3><p>{{ p.duration }} 秒 · {{ stages[p.stage] }} <span>继续创作 →</span></p><div class="project-actions"><ElButton @click="router.push(`/projects/${p.id}`)">详情</ElButton><ElButton @click="open(p)" :disabled="p.deleted">继续创作</ElButton><template v-if="allowed('edit')"><ElButton v-if="!p.deleted" @click="rename(p)">重命名</ElButton><ElButton v-if="!p.deleted" @click="duplicate(p)">复制</ElButton><ElButton v-if="!p.deleted" @click="projectApi.archive(p);save();syncProject(p)">{{ p.archived?'取消归档':'归档' }}</ElButton><ElButton v-if="!p.deleted" @click="remove(p)">删除</ElButton><ElButton v-else @click="projectApi.restore(p);save();syncProject(p)">恢复</ElButton></template></div></article><div v-if="!visible.length" class="empty"><h3>你的第一部作品，从这里开始</h3><p>在上方输入项目名称，建立专属创作空间。</p></div></div>
    </template>
    <template v-else>
      <div class="section-title"><div><ElButton text @click="save();router.push('/projects')">← 返回项目中心</ElButton><h1>{{ active.name }}</h1><small>{{ projectSync }}</small></div><ElButton @click="save();active && syncProject(active)">保存草稿</ElButton></div>
      <nav><div v-for="(s,i) in stages" :key="s" @click="navigate(i)" :class="{current:active.stage===i,done:active.stage>i}"><b>{{ i+1 }}</b>{{ s }}</div></nav>
      <section class="workspace"><aside><div class="eyebrow">CREATIVE DIRECTOR</div><h2>{{ stages[active.stage] }}</h2><p>让每一次创作都有据可依，每一个决定都清晰可控。</p><div class="note">✦ 导演建议<br><br>{{ active.stage<2 ? '提供准确的产品信息，是好故事的第一步。产品事实与创意推测将分别标注。' : '优先通过画面呈现产品差异，避免功能罗列与未经证实的效果承诺。' }}</div></aside><main><fieldset :disabled="!allowed('edit') && !(active.stage===1 && allowed('review'))" style="border:0;padding:0" v-if="active.stage<4">
        <template v-if="active.stage===0"><h2>从了解你的产品开始</h2><p>输入产品网址，我们将在演示环境中模拟资料采集。</p><label>产品网址</label><ElInput v-model="active.url" placeholder="https://your-product.com"/><label>补充产品资料（仅记录文件名，不上传）</label><IntakePanel :project-id="active.id" :url="active.url" mode="ingest"/><p class="muted">请使用脱敏演示资料。此版本不会访问网址或提交账户密码。</p></template>
        <template v-else-if="active.stage===1"><h2>核对产品理解</h2><ElTag>演示素材 · 待你核实</ElTag><ElInput v-model="active.report" type="textarea" :rows="9"/><p>请核实并编辑以上事实，再确认进入创意阶段。</p><IntakePanel :project-id="active.id" :url="active.url" mode="report"/><UnderstandingPanel :project-id="active.id"/></template>
        <CreativePanel v-else-if="active.stage===2" :project-id="active.id" :selected="active.angle" @select="active.angle=$event"/>
        <template v-else-if="active.stage===3"><h2>为故事选择合适的节奏</h2><p>{{ angles[active.angle] }}</p><ElInputNumber v-model="active.duration" :min="30" :max="120" :step="30"/><span> 秒</span><div class="note">{{ active.duration>30 ? '当前创意更适合 30 秒。长片建议增加「困境 → 探索 → 转变」完整故事章节，不重复拉伸镜头。' : '用 30 秒完成钩子、反差、产品揭示与行动号召。' }}</div><ScriptPlanner :angle="active.angle" :project-id="active.id" :duration="active.duration" :title="angles[active.angle] || active.name" @duration="active.duration=$event"/></template>
        </fieldset><ProductionPanel v-if="active.stage>=4" :key="active.id" :project-id="active.id" :duration="active.duration" :stage="active.stage" />
        <footer><span>本地草稿 · 不产生真实费用</span><ElButton v-if="active.stage<7" type="primary" @click="proceed">确认并继续 →</ElButton></footer>
      </main></section>
    </template>
  <ElDialog :model-value="!!conflict" title="项目版本差异" width="min(960px,95vw)" :close-on-click-modal="false" @close="conflict=undefined"><template v-if="conflict"><p>本地 R{{ conflict.local.serverRevision || 0 }} / 远端 R{{ conflict.revision }}。系统不会自动覆盖任何一方。</p><div v-for="d in projectDifferences(conflict.local as unknown as Record<string,unknown>,(conflict.remote || {}) as Record<string,unknown>)" :key="d.field" style="border-bottom:1px solid var(--el-border-color);padding:12px"><b>{{ d.field }}</b><pre style="white-space:pre-wrap">本地：{{ JSON.stringify(d.local) }}
远端：{{ JSON.stringify(d.remote) }}</pre></div><ElButton @click="resolveConflict(true)">保留本地并保存为远端新版本</ElButton><ElButton :disabled="!conflict.remote" @click="resolveConflict(false)">采用远端项目字段</ElButton></template></ElDialog>
  </div>
</template>
<style scoped>
.creative{padding:28px 38px;min-height:100vh;background:#f7f8fa;color:#202735}header,.brand,.section-title,footer{display:flex;align-items:center;justify-content:space-between}.brand{gap:12px}.brand b{font-size:24px}.brand span{font-size:12px;color:#8b91a0;border-left:1px solid #ddd;padding-left:14px}.hero{position:relative;overflow:hidden;background:#e9edf8;padding:52px;border-radius:20px;margin:30px 0 40px}.eyebrow{font-size:11px;letter-spacing:2px;color:#6673c5;font-weight:700}h1{font-size:32px;font-weight:700;margin:18px 0}p{line-height:1.9;color:#7a8190}h2{font-size:20px;font-weight:650;margin-bottom:20px}.hero p{max-width:600px}.create{display:flex;gap:12px;max-width:550px;margin:28px 0 16px}small{color:#8b91a0}.orb{position:absolute;right:70px;top:10px;font-size:230px;color:#8b9de0;transform:rotate(-15deg)}.section-title{margin:25px 0}.section-title span{color:#99a1b1;margin-left:10px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}.project{background:white;border:1px solid #e7eaf0;border-radius:14px;text-align:left;overflow:hidden;padding:12px;cursor:pointer}.cover{height:180px;background:#dedff5;border-radius:9px;padding:20px;display:flex;flex-direction:column;justify-content:space-between;color:#4c5092}.cover strong{font-size:28px}.cover i{font-size:10px;letter-spacing:3px}.cover-1{background:#e4ede7;color:#456f5c}.cover-2{background:#f4e8dc;color:#886647}.project-actions{display:flex;flex-wrap:wrap;gap:6px;padding:12px 0}.project h3{font-size:17px;margin:18px 8px 4px}.project p{font-size:12px;margin:4px 8px}.project p span{float:right}.empty{padding:55px;border:1px dashed #d4d9e3;border-radius:15px;grid-column:1/-1;text-align:center}nav{display:flex;justify-content:space-between;margin:30px 0}nav div{color:#a4aaba;font-size:12px}nav b{display:inline-grid;place-items:center;width:26px;height:26px;background:#e9ecf2;border-radius:50%;margin-right:7px}.current{color:#5b66c9!important}.current b,.done b{background:#6471d5;color:white}.workspace{display:grid;grid-template-columns:260px 1fr;background:white;border:1px solid #e7eaf0;border-radius:16px;overflow:hidden}aside{padding:30px;background:#f0f2f8}aside h2{margin-top:22px}.note{background:#e9edf9;border-radius:10px;padding:20px;font-size:13px;line-height:1.8;margin:25px 0;color:#64719a}main{padding:35px;min-height:430px}label{display:block;margin:25px 0 12px;font-size:13px}.muted{font-size:12px}footer{border-top:1px solid #eee;padding-top:22px;margin-top:35px}footer span{font-size:12px;color:#98a0ad}.angle{display:block;width:100%;padding:20px;border:1px solid #e2e5ed;border-radius:10px;text-align:left;margin:15px 0;cursor:pointer}.selected{border-color:#6a76d8;background:#f2f3ff}.angle h3{font-size:18px;margin-top:8px}@media(max-width:900px){.orb{display:none}.grid{grid-template-columns:1fr}.workspace{grid-template-columns:1fr}aside{display:none}nav{flex-wrap:wrap;gap:12px}.creative{padding:20px}}
</style>

